before:
public class Truncator {
    public static String truncate(String text, int max) {
        if (text.length() <= max) {
            return text;
        }
        return text.substring(0, max);
    }
}

after:
public class Truncator {
    public static String truncate(String text, int max, String suffix) {
        if (text.length() <= max) {
            return text;
        }
        return text.substring(0, max) + suffix;
    }
}

test:
public class Test {
    public static void main(String[] a) {
        if (!(Truncator.truncate("hello world", 5, "...").equals("hello..."))) throw new AssertionError("cut text");
        if (!(Truncator.truncate("hi", 5, "...").equals("hi"))) throw new AssertionError("short text unchanged");
        if (!(Truncator.truncate("abcdef", 3, "").equals("abc"))) throw new AssertionError("empty suffix");
        System.out.println("PASS");
    }
}
